def SurfaceSplit(sur,iso1){
dir=sur.NormalAtParameter(0.5,0.5);
MnmPt=(Autodesk.BoundingBox.ByGeometry(sur).MinPoint);
MxmPt=(Autodesk.BoundingBox.ByGeometry(sur).MaxPoint);
MnmPl=(Plane.ByOriginNormal(MnmPt,dir)).Translate(dir,-1);
MxmPl=(Plane.ByOriginNormal(MxmPt,dir)).Translate(dir,1);

//Creating the cutting tool
iso1Mxm=DSCore.List.Flatten(iso1.PullOntoPlane(MxmPl));
iso1Mnm=DSCore.List.Flatten(iso1.PullOntoPlane(MnmPl));

sur1=Surface.ByLoft(DSCore.List.Transpose([iso1Mnm,iso1Mxm]));
sur111=PolySurface.ByJoinedSurfaces(Flatten(sur1));

Divs1=sur.Split(sur111);
return Divs1;
};

def splitsurface(surface:var[],curves:var[]){
return = [Imperative]
{
cnt = List.Count(curves);
ind = 1..cnt-1..1;

s = SurfaceSplit(surface,curves[0]);
for (i in ind)
{
	s = SurfaceSplit(s,curves[i]);
}
return = s;
}};
